SQL_DOC.P_SQL:
SELECT RQDT.PLANT AS PLANT , RQDT.QUOTATION_NO , RQDT.QUOTATION_SEQ , RQDT.REVISION , RQDT.BUYER_ITEM_NO , RQDT.UNIT_MEASURE , QTDT.ATOB_UNIT_PRICE AS UNIT_PRICE , ATOB_REMARK AS REMARK , DECODE(RQDT.RECV_FLAG,'GD','D','C') STATUS FROM KEPRQDT RQDT, KEPQTDT QTDT WHERE RQDT.BUYER = '$G_RS.BUYER$' AND RQDT.QUOTATION_NO = '$G_RS.QUOTATION_NO$' AND RQDT.QUOTATION_SEQ= '$G_RS.QUOTATION_SEQ$' AND RQDT.REVISION = '$G_RS.REVISION$' AND RQDT.BUYER = QTDT.BUYER AND RQDT.QUOTATION_NO = QTDT.QUOTATION_NO AND RQDT.QUOTATION_SEQ= QTDT.QUOTATION_SEQ AND RQDT.REVISION = QTDT.REVISION AND QTDT.STATUS = 'C' AND QTDT.BID_SUCCESS_FLAG = 'Y'
DECLARE
V_SEND_DATE ICOMPORS.SEND_DATE%TYPE; V_SEND_TIME ICOMPORS.SEND_TIME%TYPE; V_SEND_DATETIME ICOMTRXL.KEY_8%TYPE;
BEGIN
SELECT TO_CHAR(SYSDATE,'YYYYMMDD'), TO_CHAR(SYSDATE,'HH24MISS'), TO_CHAR(SYSDATE,'YYYYMMDD HH24MISS') INTO V_SEND_DATE, V_SEND_TIME, V_SEND_DATETIME FROM DUAL;
UPDATE KEPRQDT SET SND_CHK = 'Y', SND_DATM = SYSDATE WHERE BUYER = '$G_RS.BUYER$' AND QUOTATION_NO = '$G_RS.QUOTATION_NO$' AND QUOTATION_SEQ = '$G_RS.QUOTATION_SEQ$' AND REVISION = '$G_RS.REVISION$' ;
END;
UPDATE KEPRQDT SET SND_CHK = 'E', SND_DATM = SYSDATE WHERE BUYER = '$G_RS.BUYER$' AND QUOTATION_NO = '$G_RS.QUOTATION_NO$' AND QUOTATION_SEQ = '$G_RS.QUOTATION_SEQ$' AND REVISION = '$G_RS.REVISION$'
